package fixture;import net.flashlight.battery.Power;import net.minecraft.world.item.ItemStack;public class WakeChecks{static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}public static void main(String[]a){Checks.Player p=new Checks.Player();p.off=Checks.s("flashlight:flashlight_off");Power.tick(p);ok(Checks.id(p.off).equals("flashlight:flashlight"),"first appearance lights legacy starter");ok(Power.remaining(p.off)==11999,"legacy initial charge drains normally");Power.click(p,p.off);Power.tick(p);ok(Checks.id(p.off).endsWith("_off"),"manual off persists after initialization");int before=Power.remaining(p.off);p.down=true;Power.tick(p);ok(Checks.id(p.off).endsWith("_off"),"never forcibly activates while down");p.down=false;Power.tick(p);ok(Checks.id(p.off).equals("flashlight:flashlight")&&Power.remaining(p.off)==before-1,"revival lights held lamp without recharge");Power.charge(p.off,0);p.down=true;Power.tick(p);p.down=false;Power.tick(p);ok(Checks.id(p.off).endsWith("_off")&&Power.remaining(p.off)==0,"revival never invents charge");Checks.Player late=new Checks.Player();Power.tick(late);late.off=Checks.s("flashlight:eco_off");Power.charge(late.off,400);Power.tick(late);ok(Checks.id(late.off).equals("flashlight:eco")&&Power.remaining(late.off)==399,"delayed character equipment turns on with existing charge");Checks.Player weapon=new Checks.Player();weapon.off=Checks.s("minecraft:shield");Power.tick(weapon);ok(Checks.id(weapon.off).equals("minecraft:shield"),"auto activation never replaces other offhand gear");Checks.Player client=new Checks.Player();client.world.isClientSide=true;client.off=Checks.s("flashlight:flashlight_off");Power.tick(client);ok(Checks.id(client.off).endsWith("_off"),"client cannot grant charge or switch state");System.out.println("FLASHLIGHT_SPAWN_REVIVAL_CHECKS="+n);}}
